function mergeSort(arr) {
  if (arr.length <= 1) return arr; // base case: already sorted
  const mid = Math.floor(arr.length / 2);
  const left = mergeSort(arr.slice(0, mid));
  const right = mergeSort(arr.slice(mid));
  return merge(left, right);
}

function merge(left, right) {
  const out = [];
  let i = 0, j = 0;
  while (i < left.length && j < right.length) {
    // <= takes from the left on ties, which keeps the sort stable
    if (left[i] <= right[j]) out.push(left[i++]);
    else out.push(right[j++]);
  }
  while (i < left.length) out.push(left[i++]);
  while (j < right.length) out.push(right[j++]);
  return out;
}

def merge_sort(arr):
    if len(arr) <= 1:  # base case: already sorted
        return arr
    mid = len(arr) // 2
    left = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])
    return merge(left, right)


def merge(left, right):
    out = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:  # <= keeps equal keys in order (stable)
            out.append(left[i])
            i += 1
        else:
            out.append(right[j])
            j += 1
    out.extend(left[i:])
    out.extend(right[j:])
    return out

public int[] mergeSort(int[] arr) {
    if (arr.length <= 1) return arr; // base case: already sorted
    int mid = arr.length / 2;
    int[] left = mergeSort(Arrays.copyOfRange(arr, 0, mid));
    int[] right = mergeSort(Arrays.copyOfRange(arr, mid, arr.length));
    return merge(left, right);
}

private int[] merge(int[] left, int[] right) {
    int[] out = new int[left.length + right.length];
    int i = 0, j = 0, k = 0;
    while (i < left.length && j < right.length) {
        if (left[i] <= right[j]) out[k++] = left[i++]; // <= keeps it stable
        else out[k++] = right[j++];
    }
    while (i < left.length) out[k++] = left[i++];
    while (j < right.length) out[k++] = right[j++];
    return out;
}

function quickSort(arr, lo = 0, hi = arr.length - 1) {
  if (lo >= hi) return arr; // 0 or 1 element: sorted
  const p = partition(arr, lo, hi);
  quickSort(arr, lo, p - 1);
  quickSort(arr, p + 1, hi);
  return arr;
}

function partition(arr, lo, hi) {
  const r = lo + Math.floor(Math.random() * (hi - lo + 1));
  [arr[r], arr[hi]] = [arr[hi], arr[r]]; // random pivot, moved to the end
  const pivot = arr[hi];
  let i = lo; // arr[lo..i-1] holds values <= pivot
  for (let j = lo; j < hi; j++) {
    if (arr[j] <= pivot) {
      [arr[i], arr[j]] = [arr[j], arr[i]];
      i++;
    }
  }
  [arr[i], arr[hi]] = [arr[hi], arr[i]]; // pivot lands in its final place
  return i;
}

private final Random rnd = new Random();

public void quickSort(int[] arr, int lo, int hi) {
    if (lo >= hi) return; // 0 or 1 element: sorted
    int p = partition(arr, lo, hi);
    quickSort(arr, lo, p - 1);
    quickSort(arr, p + 1, hi);
}

private int partition(int[] arr, int lo, int hi) {
    swap(arr, lo + rnd.nextInt(hi - lo + 1), hi); // random pivot, moved to the end
    int pivot = arr[hi];
    int i = lo; // arr[lo..i-1] holds values <= pivot
    for (int j = lo; j < hi; j++) {
        if (arr[j] <= pivot) {
            swap(arr, i, j);
            i++;
        }
    }
    swap(arr, i, hi); // pivot lands in its final place
    return i;
}

private void swap(int[] a, int x, int y) {
    int t = a[x]; a[x] = a[y]; a[y] = t;
}

function countingSort(nums) {
  if (nums.length === 0) return [];
  let min = nums[0], max = nums[0];
  for (const x of nums) {
    if (x < min) min = x;
    if (x > max) max = x;
  }
  const count = new Array(max - min + 1).fill(0);
  for (const x of nums) count[x - min]++; // 1) count each value
  for (let v = 1; v < count.length; v++) count[v] += count[v - 1]; // 2) prefix sums
  const out = new Array(nums.length);
  for (let i = nums.length - 1; i >= 0; i--) { // 3) right to left = stable
    const x = nums[i];
    count[x - min]--;
    out[count[x - min]] = x;
  }
  return out;
}

public int[] countingSort(int[] nums) {
    if (nums.length == 0) return nums;
    int min = nums[0], max = nums[0];
    for (int x : nums) {
        min = Math.min(min, x);
        max = Math.max(max, x);
    }
    int[] count = new int[max - min + 1];
    for (int x : nums) count[x - min]++; // 1) count each value
    for (int v = 1; v < count.length; v++) count[v] += count[v - 1]; // 2) prefix sums
    int[] out = new int[nums.length];
    for (int i = nums.length - 1; i >= 0; i--) { // 3) right to left = stable
        int x = nums[i];
        out[--count[x - min]] = x;
    }
    return out;
}

